-- Verbatim production DDL for the tables the embedding-reliability tests touch.
-- Generated by `pg_dump --schema-only` against the LIVE production database, then
-- stripped of only: comment/SET noise, ownership, and FOREIGN KEY lines (the
-- referenced tables are not recreated in the disposable database).
--
-- WHY THIS FILE EXISTS: a hand-written test schema drifts from production. An earlier
-- revision of the harness invented `parent_id`/`chunk_text` for qa_embedding_chunks
-- where production has `qa_id`/`content` plus six provenance columns — the test would
-- have validated a schema that does not exist. Deriving the fixture from the real
-- DDL removes that class of drift.

CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- ── conversation_stream (verbatim from production; only FK lines removed) ──
CREATE TABLE public.conversation_stream (
    id bigint NOT NULL,
    session_id text NOT NULL,
    role text NOT NULL,
    content text NOT NULL,
    trigger text,
    turn_id integer,
    "timestamp" timestamp with time zone NOT NULL,
    source text,
    embedding public.vector(1024),
    tool_calls jsonb,
    tool_results jsonb
);
CREATE SEQUENCE public.conversation_stream_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.conversation_stream_id_seq OWNED BY public.conversation_stream.id;
ALTER TABLE ONLY public.conversation_stream ALTER COLUMN id SET DEFAULT nextval('public.conversation_stream_id_seq'::regclass);
ALTER TABLE public.conversation_stream ADD CONSTRAINT conversation_stream_pkey PRIMARY KEY (id);
CREATE INDEX cs_session_ts_idx ON public.conversation_stream USING btree (session_id, "timestamp", role);

-- ── topics (verbatim from production; only FK lines removed) ──
CREATE TABLE public.topics (
    id bigint NOT NULL,
    topic_id text NOT NULL,
    title text NOT NULL,
    summary text,
    body text,
    body_fusion text,
    keywords text[],
    created_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now(),
    embedding public.vector(1024),
    status text DEFAULT 'active'::text,
    note_ref text,
    last_observer_ts timestamp with time zone,
    embed_model text DEFAULT ''::text NOT NULL
);
CREATE SEQUENCE public.topics_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.topics_id_seq OWNED BY public.topics.id;
ALTER TABLE ONLY public.topics ALTER COLUMN id SET DEFAULT nextval('public.topics_id_seq'::regclass);
ALTER TABLE public.topics ADD CONSTRAINT topics_pkey PRIMARY KEY (id);
ALTER TABLE public.topics ADD CONSTRAINT topics_topic_id_key UNIQUE (topic_id);
CREATE INDEX idx_topics_embedding ON public.topics USING hnsw (embedding public.vector_cosine_ops);

-- ── qa_pairs (verbatim from production; only FK lines removed) ──
CREATE TABLE public.qa_pairs (
    id bigint NOT NULL,
    source_id text NOT NULL,
    session_id text,
    turn_id text,
    question text NOT NULL,
    answer text NOT NULL,
    tool_calls jsonb DEFAULT '[]'::jsonb,
    tool_results jsonb DEFAULT '[]'::jsonb,
    "timestamp" timestamp with time zone,
    source text,
    embedding public.vector(1024),
    created_at timestamp with time zone DEFAULT now(),
    embed_model text DEFAULT ''::text NOT NULL
);
CREATE SEQUENCE public.qa_pairs_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.qa_pairs_id_seq OWNED BY public.qa_pairs.id;
ALTER TABLE ONLY public.qa_pairs ALTER COLUMN id SET DEFAULT nextval('public.qa_pairs_id_seq'::regclass);
ALTER TABLE public.qa_pairs ADD CONSTRAINT qa_pairs_compacted_pkey PRIMARY KEY (id);
CREATE INDEX idx_qp_embedding ON public.qa_pairs USING hnsw (embedding public.vector_cosine_ops);
CREATE INDEX idx_qp_session ON public.qa_pairs USING btree (session_id);
CREATE INDEX qa_pairs_answer_trgm_idx ON public.qa_pairs USING gin (answer public.gin_trgm_ops);
CREATE INDEX qa_pairs_question_trgm_idx ON public.qa_pairs USING gin (question public.gin_trgm_ops);
CREATE UNIQUE INDEX qa_pairs_source_id_key ON public.qa_pairs USING btree (source_id);

-- ── qa_embedding_chunks (verbatim from production; only FK lines removed) ──
CREATE TABLE public.qa_embedding_chunks (
    id bigint NOT NULL,
    qa_id bigint NOT NULL,
    chunk_index integer NOT NULL,
    source_field text NOT NULL,
    source_start integer NOT NULL,
    source_end integer NOT NULL,
    source_sha256 text NOT NULL,
    token_count integer NOT NULL,
    representation_version text NOT NULL,
    embedding public.vector(1024),
    embed_model text DEFAULT ''::text NOT NULL,
    content text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT qa_embedding_chunks_source_field_check CHECK ((source_field = ANY (ARRAY['question'::text, 'answer'::text]))),
    CONSTRAINT qa_embedding_chunks_source_range_valid CHECK (((source_end >= source_start) AND (source_start >= 0))),
    CONSTRAINT qa_embedding_chunks_token_count_nonneg CHECK ((token_count >= 0))
);
CREATE SEQUENCE public.qa_embedding_chunks_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.qa_embedding_chunks_id_seq OWNED BY public.qa_embedding_chunks.id;
ALTER TABLE ONLY public.qa_embedding_chunks ALTER COLUMN id SET DEFAULT nextval('public.qa_embedding_chunks_id_seq'::regclass);
ALTER TABLE public.qa_embedding_chunks ADD CONSTRAINT qa_embedding_chunks_pkey PRIMARY KEY (id);
ALTER TABLE public.qa_embedding_chunks ADD CONSTRAINT qa_embedding_chunks_qa_id_chunk_index_key UNIQUE (qa_id, chunk_index);
CREATE INDEX qa_embedding_chunks_embedding_ivfflat ON public.qa_embedding_chunks USING ivfflat (embedding public.vector_cosine_ops) WITH (lists='100');
CREATE INDEX qa_embedding_chunks_qa_id_idx ON public.qa_embedding_chunks USING btree (qa_id);

-- ── yin_paragraphs (verbatim from production; only FK lines removed) ──
CREATE TABLE public.yin_paragraphs (
    id integer NOT NULL,
    yin_version text,
    section text,
    content text,
    embedding public.vector(1024),
    created_at timestamp without time zone DEFAULT now(),
    embed_model text DEFAULT ''::text NOT NULL
);
CREATE SEQUENCE public.yin_paragraphs_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.yin_paragraphs_id_seq OWNED BY public.yin_paragraphs.id;
ALTER TABLE ONLY public.yin_paragraphs ALTER COLUMN id SET DEFAULT nextval('public.yin_paragraphs_id_seq'::regclass);
ALTER TABLE public.yin_paragraphs ADD CONSTRAINT yin_paragraphs_pkey PRIMARY KEY (id);

-- ── observation_notes (verbatim from production; only FK lines removed) ──
CREATE TABLE public.observation_notes (
    id bigint NOT NULL,
    version text NOT NULL,
    content text NOT NULL,
    source_qa_range int8range,
    prev_id bigint,
    links jsonb DEFAULT '[]'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    embedding public.vector(1024),
    embed_model text DEFAULT ''::text NOT NULL
