ALTER SEQUENCE public.observation_notes_id_seq OWNED BY public.observation_notes.id;
ALTER TABLE ONLY public.observation_notes ALTER COLUMN id SET DEFAULT nextval('public.observation_notes_id_seq'::regclass);
ALTER TABLE public.observation_notes ADD CONSTRAINT observation_notes_pkey PRIMARY KEY (id);
